{"nct": "NCT01984242", "row_index": 3, "selected_ctgov_evidence": {"arm_groups": [{"description": "Sunitinib 50 mg will be administered orally once daily on Days 1 to 28 of each 6-week cycle until disease progression. Upon disease progression, participants can crossover to receive atezolizumab and bevacizumab combination until disease progression, lack of clinical benefit, unacceptable toxicity, withdrawal from study, or study completion or termination.", "intervention_names": ["Drug: Atezolizumab (MPDL3280A), an Engineered Anti-PD-L1 Antibody", "Drug: Bevacizumab", "Drug: Sunitinib"], "label": "Sunitinib", "type": "ACTIVE_COMPARATOR"}, {"description": "Atezolizumab 1200 milligrams (mg) and bevacizumab 15 milligrams per kilogram (mg/kg) will be administered as intravenous (IV) infusions every 3 weeks (q3w) on Day 1 and Day 22 of each 6-week cycle until disease progression.", "intervention_names": ["Drug: Atezolizumab (MPDL3280A), an Engineered Anti-PD-L1 Antibody", "Drug: Bevacizumab"], "label": "Atezolizumab and Bevacizumab", "type": "EXPERIMENTAL"}, {"description": "Atezolizumab 1200 mg will be administered as IV infusion q3w on Day 1 and Day 22 of each 6-week cycle until disease progression. Upon disease progression, participants (except European Union \\[EU\\] participants) can crossover to receive atezolizumab and bevacizumab combination until disease progression, lack of clinical benefit, unacceptable toxicity, withdrawal from study, or study completion or termination.", "intervention_names": ["Drug: Atezolizumab (MPDL3280A), an Engineered Anti-PD-L1 Antibody", "Drug: Bevacizumab"], "label": "Atezolizumab", "type": "EXPERIMENTAL"}], "candidate_control_arms": [{"description": "Sunitinib 50 mg will be administered orally once daily on Days 1 to 28 of each 6-week cycle until disease progression. Upon disease progression, participants can crossover to receive atezolizumab and bevacizumab combination until disease progression, lack of clinical benefit, unacceptable toxicity, withdrawal from study, or study completion or termination.", "intervention_names": ["Drug: Atezolizumab (MPDL3280A), an Engineered Anti-PD-L1 Antibody", "Drug: Bevacizumab", "Drug: Sunitinib"], "label": "Sunitinib", "type": "ACTIVE_COMPARATOR"}], "interventions": [{"arm_group_labels": ["Atezolizumab", "Atezolizumab and Bevacizumab", "Sunitinib"], "description": "Atezolizumab will be administered according to the dosage schedule mentioned in the arm description.", "name": "Atezolizumab (MPDL3280A), an Engineered Anti-PD-L1 Antibody", "other_names": ["Tecentriq", "MPDL3280A", "RO5541267"], "type": "DRUG"}, {"arm_group_labels": ["Atezolizumab", "Atezolizumab and Bevacizumab", "Sunitinib"], "description": "Bevacizumab will be administered according to the dosage schedule mentioned in the arm description.", "name": "Bevacizumab", "other_names": ["Avastin"], "type": "DRUG"}]}, "trial_name": "IMmotion150"}
{"nct": "NCT02420821", "row_index": 4, "selected_ctgov_evidence": {"arm_groups": [{"description": "Participants will receive sunitinib until loss of clinical benefit, unacceptable toxicity or symptomatic deterioration attributed to disease progression, withdrawal of consent, or death, whichever occurs first.", "intervention_names": ["Drug: Sunitinib"], "label": "Sunitinib", "type": "ACTIVE_COMPARATOR"}, {"description": "Participants will receive both atezolizumab and bevacizumab until loss of clinical benefit, unacceptable toxicity or symptomatic deterioration attributed to disease progression, withdrawal of consent, or death, whichever occurs first.", "intervention_names": ["Drug: Atezolizumab (MPDL3280A), an engineered anti-PD-L1 antibody", "Drug: Bevacizumab"], "label": "Atezolizumab + Bevacizumab", "type": "EXPERIMENTAL"}], "candidate_control_arms": [{"description": "Participants will receive sunitinib until loss of clinical benefit, unacceptable toxicity or symptomatic deterioration attributed to disease progression, withdrawal of consent, or death, whichever occurs first.", "intervention_names": ["Drug: Sunitinib"], "label": "Sunitinib", "type": "ACTIVE_COMPARATOR"}], "interventions": [{"arm_group_labels": ["Atezolizumab + Bevacizumab"], "description": "Atezolizumab will be administered at a fixed dose of 1200 milligrams (mg) via intravenous (IV) infusion on Days 1 and 22 of each 42-day cycle.", "name": "Atezolizumab (MPDL3280A), an engineered anti-PD-L1 antibody", "other_names": ["Tecentriq, MPDL3280A"], "type": "DRUG"}, {"arm_group_labels": ["Atezolizumab + Bevacizumab"], "description": "Bevacizumab will be administered at a dose of 15 milligrams per kilogram (mg/kg) via IV infusion on Days 1 and 22 of each 42-day cycle.", "name": "Bevacizumab", "other_names": ["Avastin"], "type": "DRUG"}]}, "trial_name": "IMmotion151"}
{"nct": "NCT02763579", "row_index": 5, "selected_ctgov_evidence": {"arm_groups": [{"description": "Participants received intravenous infusions of placebo in combination with carboplatin to achieve an initial target AUC of 5 mg/mL/min followed by etoposide 100 mg/m\\^2 on Day 1 of every 21-day cycle during the induction phase (Cycles 1-4). On Days 2 and 3 of every 21-day cycle during the induction phase (Cycles 1-4), etoposide 100 mg/m\\^2 was administered alone. Thereafter, participants received maintenance (Cycle 5 onward) placebo on Day 1 of every 21-day cycle until persistent radiographic PD, symptomatic deterioration, intolerable toxicity, withdrawal of consent, death, or study termination by the Sponsor.", "intervention_names": ["Drug: Carboplatin", "Drug: Etoposide", "Drug: Placebo"], "label": "Placebo + Carboplatin + Etoposide", "type": "ACTIVE_COMPARATOR"}, {"description": "Participants received intravenous infusions of atezolizumab 1200 milligrams (mg) in combination with carboplatin to achieve an initial target area under the concentration-time curve (AUC) of 5 milligrams per milliliter per minute (mg/mL/min) followed by etoposide 100 milligrams per square meter (mg/m\\^2) on Day 1 of every 21-day cycle during the induction phase (Cycles 1-4). On Days 2 and 3 of every 21-day cycle during the induction phase (Cycles 1-4), etoposide 100 mg/m\\^2 was administered alone. Thereafter, participants received maintenance (Cycle 5 onward) atezolizumab 1200 mg on Day 1 of every 21-day cycle until persistent radiographic PD, symptomatic deterioration, intolerable toxicity, withdrawal of consent, death, or study termination by the Sponsor.", "intervention_names": ["Drug: Atezolizumab (MPDL3280A), an engineered anti-PD-L1 antibody", "Drug: Carboplatin", "Drug: Etoposide"], "label": "Atezolizumab + Carboplatin + Etoposide", "type": "EXPERIMENTAL"}], "candidate_control_arms": [{"description": "Participants received intravenous infusions of placebo in combination with carboplatin to achieve an initial target AUC of 5 mg/mL/min followed by etoposide 100 mg/m\\^2 on Day 1 of every 21-day cycle during the induction phase (Cycles 1-4). On Days 2 and 3 of every 21-day cycle during the induction phase (Cycles 1-4), etoposide 100 mg/m\\^2 was administered alone. Thereafter, participants received maintenance (Cycle 5 onward) placebo on Day 1 of every 21-day cycle until persistent radiographic PD, symptomatic deterioration, intolerable toxicity, withdrawal of consent, death, or study termination by the Sponsor.", "intervention_names": ["Drug: Carboplatin", "Drug: Etoposide", "Drug: Placebo"], "label": "Placebo + Carboplatin + Etoposide", "type": "ACTIVE_COMPARATOR"}], "interventions": [{"arm_group_labels": ["Atezolizumab + Carboplatin + Etoposide", "Placebo + Carboplatin + Etoposide"], "description": "Carboplatin intravenous infusion to achieve an initial target AUC of 5 mg/mL/min was administered on Day 1 of each 21-day cycle during the induction phase (Cycles 1-4).", "name": "Carboplatin", "other_names": [], "type": "DRUG"}, {"arm_group_labels": ["Atezolizumab + Carboplatin + Etoposide", "Placebo + Carboplatin + Etoposide"], "description": "Etoposide intravenous infusion was administered at a dose of 100 mg/m\\^2 on Days 1, 2, and 3 of each 21-day cycle during the induction phase (Cycles 1-4).", "name": "Etoposide", "other_names": [], "type": "DRUG"}, {"arm_group_labels": ["Placebo + Carboplatin + Etoposide"], "description": "Placebo intravenous infusion was administered on Day 1 of each 21-day cycle during the induction phase (Cycles 1-4) and maintenance phase (Cycle 5 onward).", "name": "Placebo", "other_names": [], "type": "DRUG"}, {"arm_group_labels": ["Atezolizumab + Carboplatin + Etoposide"], "description": "Atezolizumab intravenous infusion was administered at a dose of 1200 mg on Day 1 of each 21-day cycle during the induction phase (Cycles 1-4) and maintenance phase (Cycle 5 onward).", "name": "Atezolizumab (MPDL3280A), an engineered anti-PD-L1 antibody", "other_names": ["MPDL3280A, RO5541267, Tecentriq"], "type": "DRUG"}]}, "trial_name": "IMPower 133"}
{"nct": "NCT02366143", "row_index": 6, "selected_ctgov_evidence": {"arm_groups": [{"description": "Participants received IV infusion of bevacizumab on Day 1 of each 21-day cycle followed by IV infusion of paclitaxel and carboplatin on Day 1 of each 21-day cycle for 4 or 6 cycles or loss of clinical benefit whichever occurs first, during induction treatment phase. Participants received IV infusion of bevacizumab during maintenance treatment phase until progressive disease, unacceptable toxicity, or death.", "intervention_names": ["Drug: Bevacizumab", "Drug: Carboplatin", "Drug: Paclitaxel"], "label": "Arm C (Bevacizumab+Paclitaxel+Carboplatin)", "type": "ACTIVE_COMPARATOR"}, {"description": "Participants received intravenous (IV) infusion of atezolizumab on Day 1 of each 21-day cycle followed by IV infusion of paclitaxel and carboplatin on Day 1 of each 21-day cycle for 4 or 6 cycles or until loss of clinical benefit whichever occurs first, during induction treatment phase. Participants received IV infusion of atezolizumab during maintenance treatment phase until loss of clinical benefit.", "intervention_names": ["Drug: Atezolizumab (MPDL3280A), an engineered anti-PD-L1 antibody", "Drug: Carboplatin", "Drug: Paclitaxel"], "label": "Arm A (Atezolizumab+Paclitaxel+Carboplatin)", "type": "EXPERIMENTAL"}, {"description": "Participants received IV infusion of atezolizumab and bevacizumab on Day 1 of each 21-day cycle followed by IV infusion of paclitaxel and carboplatin on Day 1 of each 21-day cycle for 4 or 6 cycles or until loss of clinical benefit whichever occurs first, during induction treatment phase. Participants received IV infusion of atezolizumab until loss of clinical benefit and bevacizumab until progressive disease, unacceptable toxicity, or death during maintenance treatment phase.", "intervention_names": ["Drug: Atezolizumab (MPDL3280A), an engineered anti-PD-L1 antibody", "Drug: Bevacizumab", "Drug: Carboplatin", "Drug: Paclitaxel"], "label": "Arm B (Atezolizumab+Bevacizumab+Paclitaxel + Carboplatin)", "type": "EXPERIMENTAL"}], "candidate_control_arms": [{"description": "Participants received IV infusion of bevacizumab on Day 1 of each 21-day cycle followed by IV infusion of paclitaxel and carboplatin on Day 1 of each 21-day cycle for 4 or 6 cycles or loss of clinical benefit whichever occurs first, during induction treatment phase. Participants received IV infusion of bevacizumab during maintenance treatment phase until progressive disease, unacceptable toxicity, or death.", "intervention_names": ["Drug: Bevacizumab", "Drug: Carboplatin", "Drug: Paclitaxel"], "label": "Arm C (Bevacizumab+Paclitaxel+Carboplatin)", "type": "ACTIVE_COMPARATOR"}], "interventions": [{"arm_group_labels": ["Arm A (Atezolizumab+Paclitaxel+Carboplatin)", "Arm B (Atezolizumab+Bevacizumab+Paclitaxel + Carboplatin)"], "description": "Atezolizumab was administered as IV infusion at a dose of 1200 milligrams (mg) on Day 1 of each 21-day cycle until loss of clinical benefit.", "name": "Atezolizumab (MPDL3280A), an engineered anti-PD-L1 antibody", "other_names": ["MPDL3280A", "RO5541267", "Tecentriq"], "type": "DRUG"}, {"arm_group_labels": ["Arm B (Atezolizumab+Bevacizumab+Paclitaxel + Carboplatin)", "Arm C (Bevacizumab+Paclitaxel+Carboplatin)"], "description": "Bevacizumab was administered as IV infusion at a dose of 15 milligrams per kilogram (mg/kg) on Day 1 of each 21-day cycle until progressive disease, unacceptable toxicity, or death.", "name": "Bevacizumab", "other_names": [], "type": "DRUG"}, {"arm_group_labels": ["Arm A (Atezolizumab+Paclitaxel+Carboplatin)", "Arm B (Atezolizumab+Bevacizumab+Paclitaxel + Carboplatin)", "Arm C (Bevacizumab+Paclitaxel+Carboplatin)"], "description": "Carboplatin was administered at area under the concentration-time curve (AUC) 6 milligrams per milliliter per minute (mg/mL/min) on Day 1 of each 21-day cycle for 4 or 6 cycles or until loss of clinical benefit whichever occurs first.", "name": "Carboplatin", "other_names": [], "type": "DRUG"}, {"arm_group_labels": ["Arm A (Atezolizumab+Paclitaxel+Carboplatin)", "Arm B (Atezolizumab+Bevacizumab+Paclitaxel + Carboplatin)", "Arm C (Bevacizumab+Paclitaxel+Carboplatin)"], "description": "Paclitaxel was administered as IV infusion at a dose of 200 milligrams per square meter (mg/m\\^2) on Day 1 of each 21-day cycle for 4 or 6 cycles or until loss of clinical benefit whichever occurs first.", "name": "Paclitaxel", "other_names": [], "type": "DRUG"}]}, "trial_name": "IMPower150"}
