{"nct": "NCT02367781", "row_index": 8, "selected_ctgov_evidence": {"arm_groups": [{"description": "Participants received IV infusion of carboplatin on Day 1 and nab-paclitaxel on Days 1, 8, and 15 of each 21-day cycle for 4 or 6 cycles or until disease progression whichever occurred first during induction treatment phase. Participants received best supportive care during maintenance treatment phase. Switch maintenance to pemetrexed was also permitted. Participants who were consented prior to approval of protocol Version 5 were given the option to cross over to receive atezolizumab as monotherapy until disease progression.", "intervention_names": ["Drug: Atezolizumab (MPDL3280A), an engineered anti-PD-L1 antibody", "Drug: Carboplatin", "Drug: Nab-Paclitaxel", "Drug: Pemetrexed"], "label": "Arm B (Nab-Paclitaxel+Carboplatin)", "type": "ACTIVE_COMPARATOR"}, {"description": "Participants received intravenous (IV) infusion of atezolizumab and carboplatin on Day 1 of each 21-day cycle, and nab-paclitaxel on Days 1, 8, and 15 of each 21-day cycle for 4 or 6 cycles or until loss of clinical benefit whichever occurred first during induction treatment phase. Participants received IV infusion of atezolizumab during maintenance treatment phase until loss of clinical benefit.", "intervention_names": ["Drug: Atezolizumab (MPDL3280A), an engineered anti-PD-L1 antibody", "Drug: Carboplatin", "Drug: Nab-Paclitaxel"], "label": "Arm A (Atezolizumab+Nab-Paclitaxel+Carboplatin)", "type": "EXPERIMENTAL"}], "candidate_control_arms": [{"description": "Participants received IV infusion of carboplatin on Day 1 and nab-paclitaxel on Days 1, 8, and 15 of each 21-day cycle for 4 or 6 cycles or until disease progression whichever occurred first during induction treatment phase. Participants received best supportive care during maintenance treatment phase. Switch maintenance to pemetrexed was also permitted. Participants who were consented prior to approval of protocol Version 5 were given the option to cross over to receive atezolizumab as monotherapy until disease progression.", "intervention_names": ["Drug: Atezolizumab (MPDL3280A), an engineered anti-PD-L1 antibody", "Drug: Carboplatin", "Drug: Nab-Paclitaxel", "Drug: Pemetrexed"], "label": "Arm B (Nab-Paclitaxel+Carboplatin)", "type": "ACTIVE_COMPARATOR"}], "interventions": [{"arm_group_labels": ["Arm A (Atezolizumab+Nab-Paclitaxel+Carboplatin)", "Arm B (Nab-Paclitaxel+Carboplatin)"], "description": "Atezolizumab was administered as IV infusion at a dose of 1200 milligrams (mg) on Day 1 of each 21-day cycle. Atezolizumab was administered to participants who were randomized to \"Arm A (Atezolizumab + Nab-Paclitaxel + Carboplatin)\" and to participants in \"Arm B (Nab-Paclitaxel + Carboplatin)\" who cross over at progression.", "name": "Atezolizumab (MPDL3280A), an engineered anti-PD-L1 antibody", "other_names": ["MPDL3280A, RO5541267, Tecentriq"], "type": "DRUG"}, {"arm_group_labels": ["Arm A (Atezolizumab+Nab-Paclitaxel+Carboplatin)", "Arm B (Nab-Paclitaxel+Carboplatin)"], "description": "Carboplatin was administered at area under the concentration curve (AUC) 6 milligrams per milliliter per minute (mg/mL/min) on Day 1 of each 21-day cycle.", "name": "Carboplatin", "other_names": [], "type": "DRUG"}, {"arm_group_labels": ["Arm A (Atezolizumab+Nab-Paclitaxel+Carboplatin)", "Arm B (Nab-Paclitaxel+Carboplatin)"], "description": "Nab-paclitaxel was administered as IV infusion at a dose of 100 milligrams per square meter (mg/m\\^2) on Days 1, 8, and 15 of each 21-day cycle.", "name": "Nab-Paclitaxel", "other_names": [], "type": "DRUG"}, {"arm_group_labels": ["Arm B (Nab-Paclitaxel+Carboplatin)"], "description": "Switch maintenance to pemetrexed can be administered within 6 weeks of Day 1 of the last induction cycle.", "name": "Pemetrexed", "other_names": [], "type": "DRUG"}]}, "trial_name": "IMpower130"}
{"nct": "NCT02425891", "row_index": 9, "selected_ctgov_evidence": {"arm_groups": [{"description": "Participants assigned to placebo plus nab-paclitaxel received both agents until disease progression or unacceptable toxicity.", "intervention_names": ["Drug: Nab-Paclitaxel", "Drug: Placebo"], "label": "Placebo Plus Nab-Paclitaxel", "type": "PLACEBO_COMPARATOR"}, {"description": "Participants assigned to atezolizumab plus nab-paclitaxel received both agents until disease progression or unacceptable toxicity.", "intervention_names": ["Drug: Atezolizumab (MPDL3280A), an engineered anti-PDL1 antibody", "Drug: Nab-Paclitaxel"], "label": "Atezolizumab Plus Nab-Paclitaxel", "type": "EXPERIMENTAL"}], "candidate_control_arms": [{"description": "Participants assigned to placebo plus nab-paclitaxel received both agents until disease progression or unacceptable toxicity.", "intervention_names": ["Drug: Nab-Paclitaxel", "Drug: Placebo"], "label": "Placebo Plus Nab-Paclitaxel", "type": "PLACEBO_COMPARATOR"}], "interventions": [{"arm_group_labels": ["Atezolizumab Plus Nab-Paclitaxel", "Placebo Plus Nab-Paclitaxel"], "description": "Nab-Paclitaxel at a starting dose of 100 milligrams per square meter via IV infusion on Days 1, 8, and 15 of each 28-day cycle. Nab-Paclitaxel was administered for a target of at least 6 cycles, with no maximum in the absence of disease progression or unacceptable toxicity.", "name": "Nab-Paclitaxel", "other_names": ["Abraxane®"], "type": "DRUG"}, {"arm_group_labels": ["Placebo Plus Nab-Paclitaxel"], "description": "Placebo administered via IV infusion on Days 1 and 15 of each 28-day cycle until disease progression or unacceptable toxicity.", "name": "Placebo", "other_names": [], "type": "DRUG"}, {"arm_group_labels": ["Atezolizumab Plus Nab-Paclitaxel"], "description": "Atezolizumab at a fixed dose of 840 milligrams via intravenous (IV) infusion on Days 1 and 15 of each 28-day cycle until disease progression or unacceptable toxicity.", "name": "Atezolizumab (MPDL3280A), an engineered anti-PDL1 antibody", "other_names": ["Tecentriq, MPDL3280A"], "type": "DRUG"}]}, "trial_name": "IMpassion130"}
