{"nct": "NCT02367794", "row_index": 11, "selected_ctgov_evidence": {"arm_groups": [{"description": "The induction phase of the study will consist of four or six cycles; carboplatin will be administered on Day 1 of each 21-day cycle, nab-paclitaxel will be administered on Days 1, 8, and 15 of each 21-day cycle. The Day 1 order of drug administration is as follows: nab-paclitaxel, then carboplatin. Participants who experience disease progression at any time during the induction phase will discontinue all study treatment. In the maintenance phase, participants will receive best supportive care.", "intervention_names": ["Drug: Carboplatin", "Drug: Nab-Paclitaxel"], "label": "Arm C: Nab-Paclitaxel + Carboplatin", "type": "ACTIVE_COMPARATOR"}, {"description": "The induction phase of the study will consist of four or six cycles; atezolizumab, paclitaxel, and carboplatin will be administered on Day 1 of each 21-day cycle. The Day 1 order of drug administration is as follows: atezolizumab, then paclitaxel, then carboplatin. Participants who experience no further clinical benefit at any time during the induction phase will discontinue all study treatments. In the absence of the above criteria, after the 4- or 6-cycle induction phase, participants will begin maintenance therapy with atezolizumab. Atezolizumab will be continued as long as there is a clinical benefit to the participant.", "intervention_names": ["Drug: Atezolizumab (MPDL3280A), an engineered anti-programmed death-ligand 1 (anti-PD-L1) antibody", "Drug: Carboplatin", "Drug: Paclitaxel"], "label": "Arm A: Atezolizumab + Paclitaxel + Carboplatin", "type": "EXPERIMENTAL"}, {"description": "The induction phase of the study will consist of four or six cycles; atezolizumab and carboplatin will be administered on Day 1 of each 21-day cycle. Nab-Paclitaxel will be administered on Days 1, 8, and 15 of each 21-day cycle. The Day 1 order of drug administration is as follows: atezolizumab, then nab-paclitaxel, then carboplatin. Participants who experience no further clinical benefit at any time during the induction phase will discontinue all study treatments. In the absence of the above criteria, after the 4- or 6-cycle induction phase, participants will begin maintenance therapy with atezolizumab. Atezolizumab will be continued as long as there is a clinical benefit to the participant.", "intervention_names": ["Drug: Atezolizumab (MPDL3280A), an engineered anti-programmed death-ligand 1 (anti-PD-L1) antibody", "Drug: Carboplatin", "Drug: Nab-Paclitaxel"], "label": "Arm B: Atezolizumab + Nab-Paclitaxel + Carboplatin", "type": "EXPERIMENTAL"}], "candidate_control_arms": [{"description": "The induction phase of the study will consist of four or six cycles; carboplatin will be administered on Day 1 of each 21-day cycle, nab-paclitaxel will be administered on Days 1, 8, and 15 of each 21-day cycle. The Day 1 order of drug administration is as follows: nab-paclitaxel, then carboplatin. Participants who experience disease progression at any time during the induction phase will discontinue all study treatment. In the maintenance phase, participants will receive best supportive care.", "intervention_names": ["Drug: Carboplatin", "Drug: Nab-Paclitaxel"], "label": "Arm C: Nab-Paclitaxel + Carboplatin", "type": "ACTIVE_COMPARATOR"}], "interventions": [{"arm_group_labels": ["Arm A: Atezolizumab + Paclitaxel + Carboplatin", "Arm B: Atezolizumab + Nab-Paclitaxel + Carboplatin"], "description": "Atezolizumab 1200 milligrams (mg) intravenous infusion (IV) on day 1 of each 21-day cycle.", "name": "Atezolizumab (MPDL3280A), an engineered anti-programmed death-ligand 1 (anti-PD-L1) antibody", "other_names": ["Tecentriq"], "type": "DRUG"}, {"arm_group_labels": ["Arm A: Atezolizumab + Paclitaxel + Carboplatin", "Arm B: Atezolizumab + Nab-Paclitaxel + Carboplatin", "Arm C: Nab-Paclitaxel + Carboplatin"], "description": "Carboplatin area under the concentration curve (AUC) 6 milligrams per milliliter per minute (mg/mL/min) on Day 1 of each 21-day cycle for 4 or 6 cycles.", "name": "Carboplatin", "other_names": [], "type": "DRUG"}, {"arm_group_labels": ["Arm B: Atezolizumab + Nab-Paclitaxel + Carboplatin", "Arm C: Nab-Paclitaxel + Carboplatin"], "description": "Nab-paclitaxel 100 milligrams per meter squared (mg/m\\^2) IV on Day 1, 8, and 15 of each 21-day cycle for 4 or 6 cycles.", "name": "Nab-Paclitaxel", "other_names": [], "type": "DRUG"}, {"arm_group_labels": ["Arm A: Atezolizumab + Paclitaxel + Carboplatin"], "description": "Paclitaxel 200 mg/m\\^2 IV on Day 1 of each 21-day cycle for 4 or 6 cycles. Participants of Asian race/ethnicity will be administered paclitaxel 175 mg/m\\^2 IV.", "name": "Paclitaxel", "other_names": [], "type": "DRUG"}]}, "trial_name": "IMpower131"}
