": ["Drug: Atezolizumab Placebo", "Drug: Cobimetinib", "Drug: Vemurafenib"], "label": "Atezolizumab Placebo + Cobimetinib + Vemurafenib", "type": "EXPERIMENTAL"}], "interventions": [{"arm_group_labels": ["Atezolizumab + Cobimetinib + Vemurafenib + Vemurafenib Placebo"], "description": "Will be administered as per the schedule described in individual arm.", "name": "Atezolizumab", "other_names": [], "type": "DRUG"}, {"arm_group_labels": ["Atezolizumab Placebo + Cobimetinib + Vemurafenib"], "description": "Will be administered as per the schedule described in individual arm.", "name": "Atezolizumab Placebo", "other_names": [], "type": "DRUG"}, {"arm_group_labels": ["Atezolizumab + Cobimetinib + Vemurafenib + Vemurafenib Placebo", "Atezolizumab Placebo + Cobimetinib + Vemurafenib"], "description": "Will be administered as per the schedule described in individual arm.", "name": "Cobimetinib", "other_names": [], "type": "DRUG"}, {"arm_group_labels": ["Atezolizumab + Cobimetinib + Vemurafenib + Vemurafenib Placebo", "Atezolizumab Placebo + Cobimetinib + Vemurafenib"], "description": "Will be administered as per the schedule described in individual arm.", "name": "Vemurafenib", "other_names": [], "type": "DRUG"}, {"arm_group_labels": ["Atezolizumab + Cobimetinib + Vemurafenib + Vemurafenib Placebo"], "description": "Will be administered as per the schedule described in individual arm.", "name": "Vemurafenib Placebo", "other_names": [], "type": "DRUG"}]}, "trial_name": "IMspire150"}
